engine.buildAmendment:
function buildAmendment(input) {
  var mode = String((input && input.mode) || "amend");           // renew | renew_amend | amend
  var noCost = !!(input && input.noCost);
  var deal = (input && input.deal) || {};
  var renewal = (input && input.renewal) || {};
  var clauseEdits = Array.isArray(input && input.clauseEdits) ? input.clauseEdits : [];

  function s(v, fallback) { var x = String(v == null ? "" : v).trim(); return x || (fallback || ""); }
  var title = s(deal.title, "[TITLE OF AGREEMENT]");
  var partyA = s(deal.partyA, "[PARTY A]");
  var partyB = s(deal.partyB, "[PARTY B]");
  var effDate = s(deal.effectiveDate, "[ORIGINAL EFFECTIVE DATE]");
  var nextNum = parseInt(deal.nextNumber, 10);
  if (isNaN(nextNum) || nextNum < 1) nextNum = 1;
  var priorList = Array.isArray(deal.priorAmendments) ? deal.priorAmendments : [];
  var amendDate = s(input && input.amendmentDate, "[AMENDMENT DATE]");
  var newEndDate = s(renewal.newEndDate, "[NEW EXPIRATION DATE]");

  var ORDINALS = ["First", "Second", "Third", "Fourth", "Fifth", "Sixth", "Seventh", "Eighth", "Ninth", "Tenth"];
  var ordinal = nextNum <= 10 ? ORDINALS[nextNum - 1] : "No. " + nextNum;
  var amendTitle = (nextNum <= 10 ? ordinal.toUpperCase() + " AMENDMENT" : "AMENDMENT NO. " + nextNum) + " TO " + title.toUpperCase();

  // ── Recitals ──────────────────────────────────────────────────────
  var amendedChain = "";
  if (priorList.length) {
    amendedChain = ", as amended by " + priorList.map(function (p, i) {
      var n = s(p.label, (ORDINALS[i] || ("Amendment No. " + (i + 1))) + " Amendment");
      return n + (p.date ? " dated " + s(p.date) : "");
    }).join(", ") + (priorList.length > 1 ? " (collectively, the “Prior Amendments”)" : "");
  }
  var recitals = [];
  recitals.push("WHEREAS, " + partyA + " and " + partyB + " are parties to that certain " + title +
    " dated as of " + effDate + amendedChain + " (the “Agreement”);");
  if (mode === "renew" || mode === "renew_amend") {
    recitals.push("WHEREAS, the parties desire to extend the term of the Agreement" +
      (noCost ? " at no additional cost to either party" : "") +
      (mode === "renew_amend" ? " and to further amend the Agreement as set forth herein" : "") + ";");
  } else {
    recitals.push("WHEREAS, the parties desire to amend the Agreement as set forth herein;");
  }
  recitals.push("NOW, THEREFORE, in consideration of the mutual covenants contained herein and other good and valuable consideration, the receipt and sufficiency of which are hereby acknowledged, the parties agree as follows:");

  // ── Operative clauses ─────────────────────────────────────────────
  var ops = [];
  var opNum = 1;
  if (mode === "renew" || mode === "renew_amend") {
    var extSentence = "The term of the Agreement is hereby extended and shall continue in full force and effect through and including " + newEndDate +
      (s(renewal.extendText) ? " (" + s(renewal.extendText) + ")" : "") + ", unless earlier terminated in accordance with the Agreement.";
    if (noCost) {
      extSentence += " The extension set forth in this Section is at no additional cost: all fees, rates, and charges under the Agreement remain unchanged and no additional fees shall be payable in respect of the extended term.";
    }
    ops.push({ head: "Extension of Term", body: extSentence });
    opNum++;
  }
  clauseEdits.forEach(function (ce) {
    var label = s(ce.number) ? "Section " + s(ce.number) + (s(ce.label) ? " (" + s(ce.label) + ")" : "") : s(ce.label, "[SECTION]");
    ops.push({
      head: "Amendment of " + label,
      body: label + " of the Agreement is hereby deleted in its entirety and replaced with the following:\n\n“" +
        s(ce.newText, "[REPLACEMENT TEXT]") + "”",
    });
    opNum++;
  });
  ops.push({
    head: "Effect of Amendment",
    body: "Except as expressly amended hereby, all terms and conditions of the Agreement remain unmodified and in full force and effect. " +
      "In the event of any conflict between this Amendment and the Agreement, this Amendment controls. " +
      "Capitalized terms used but not defined in this Amendment have the meanings given to them in the Agreement.",
  });
  ops.push({
    head: "Counterparts",
    body: "This Amendment may be executed in counterparts (including by electronic signature), each of which is deemed an original and all of which together constitute one instrument.",
  });

  // ── Assemble plain text + simple HTML ─────────────────────────────
  var lines = [];
  lines.push(amendTitle);
  lines.push("");
  lines.push("This " + (nextNum <= 10 ? ordinal + " Amendment" : "Amendment No. " + nextNum) +
    " (this “Amendment”) is entered into as of " + amendDate + " by and between " + partyA + " and " + partyB + ".");
  lines.push("");
  recitals.forEach(function (r) { lines.push(r); lines.push(""); });
  ops.forEach(function (o, i) {
    lines.push((i + 1) + ". " + o.head + ". " + o.body);
    lines.push("");
  });
  lines.push("IN WITNESS WHEREOF, the parties have executed this Amendment as of the date first written above.");
  lines.push("");
  lines.push(partyA.toUpperCase());
  lines.push("By: _______________________________");
  lines.push("Name:");
  lines.push("Title:");
  lines.push("");
  lines.push(partyB.toUpperCase());
  lines.push("By: _______________________________");
  lines.push("Name:");
  lines.push("Title:");
  var bodyText = lines.join("\n");

  function esc(x) {
    return String(x == null ? "" : x)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }
  var html = [];
  html.push("<p style='text-align:center'><b>" + esc(amendTitle) + "</b></p>");
  html.push("<p>This " + esc(nextNum <= 10 ? ordinal + " Amendment" : "Amendment No. " + nextNum) +
    " (this &ldquo;Amendment&rdquo;) is entered into as of " + esc(amendDate) +
    " by and between <b>" + esc(partyA) + "</b> and <b>" + esc(partyB) + "</b>.</p>");
  recitals.forEach(function (r) { html.push("<p>" + esc(r) + "</p>"); });
  ops.forEach(function (o, i) {
    html.push("<p><b>" + (i + 1) + ". " + esc(o.head) + ".</b> " + esc(o.body).replace(/\n\n/g, "</p><p style='margin-left:24px'>") + "</p>");
  });
  html.push("<p>IN WITNESS WHEREOF, the parties have executed this Amendment as of the date first written above.</p>");
  html.push("<p><b>" + esc(partyA.toUpperCase()) + "</b><br>By: _______________________________<br>Name:<br>Title:</p>");
  html.push("<p><b>" + esc(partyB.toUpperCase()) + "</b><br>By: _______________________________<br>Name:<br>Title:</p>");

  return {
    title: amendTitle,
    bodyText: bodyText,
    bodyHtml: html.join(""),
    overview: amendTitle + " · " + ops.length + " operative clauses",
    provenance: {
      kernelVersion: (typeof window !== "undefined" && window.eli && window.eli.kernelVersion) || "v3",
      toolVersion: "v1.0",
      docHash: null,
      timestamp: Date.now(),
    },
  };
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.host || !eli.ai) return;
  var bundle = eli.tools && eli.tools._loaded && eli.tools._loaded.amendment_builder;
  if (!bundle) return;
  var efns = bundle._eliEngineFns || {};
  var buildAmendment = efns.buildAmendment;

  var S = null; // wizard state — reset per launch

  function _freshState() {
    return {
      step: 1,
      mode: null,            // "renew" | "renew_amend" | "amend"
      noCost: null,          // true | false (renew modes only)
      source: null,          // { kind: "open"|"docx"|"pdf", name, text }
      deal: { title: "", partyA: "", partyB: "", effectiveDate: "", termSummary: "", nextNumber: 1, priorAmendments: [] },
      sections: [],          // [{ id, number, label, text }]
      selected: {},          // sectionId → true
      edits: {},             // sectionId → edited text
      renewal: { newEndDate: "", extendText: "" },
      amendmentDate: new Date().toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" }),
      generated: null,
    };
  }

  function _esc(x) {
    return String(x == null ? "" : x)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _toast(msg, tone) { if (typeof showToast === "function") showToast(msg, tone || "info"); }

  // ── Source readers ────────────────────────────────────────────────
  function _readOpenDoc() {
    return eli.host.runRaw("amend:read_open", function (context) {
      var body = context.document.body;
      body.load("text");
      return context.sync().then(function () { return String(body.text || ""); });
    });
  }
  function _readDocxFile(file) {
    if (!window.mammoth || !window.mammoth.extractRawText) {
      return Promise.reject(new Error("Word-file reader (mammoth) isn't loaded in this session — use “the open document” instead, or open the file in Word first."));
    }
    return file.arrayBuffer().then(function (buf) {
      return window.mammoth.extractRawText({ arrayBuffer: buf });
    }).then(function (res) { return String((res && res.value) || ""); });
  }
  function _readPdfFile(file) {
    var lib = window.pdfjsLib || window.pdfjs;
    if (!lib || !lib.getDocument) {
      return Promise.reject(new Error("PDF reader isn't loaded in this session — upload the Word version, or open the document in Word."));
    }
    return file.arrayBuffer().then(function (buf) {
      return lib.getDocument({ data: buf }).promise;
    }).then(function (pdf) {
      var pages = [];
      var chain = Promise.resolve();
      for (var i = 1; i <= pdf.numPages; i++) {
        (function (n) {
          chain = chain.then(function () {
            return pdf.getPage(n).then(function (page) { return page.getTextContent(); })
              .then(function (tc) {
                pages.push(tc.items.map(function (it) { return it.str; }).join(" "));
              });
          });
        })(i);
      }
      return chain.then(function () { return pages.join("\n\n"); });
    });
  }

  // ── AI deal parse (the only AI call) ──────────────────────────────
  function _aiParseDeal(text) {
    var prompt =
      "Read this executed agreement and extract deal facts. Return STRICT RAW JSON only:\n" +
      '{"title":"<agreement title, e.g. Master Services Agreement>",' +
      '"partyA":"<first party full legal name>","partyB":"<second party full legal name>",' +
      '"effectiveDate":"<original effective date as written>",' +
      '"termSummary":"<1 sentence: current term + expiration + any renewal option/notice requirement>",' +
      '"currentEndDate":"<current expiration date if determinable, else empty>",' +
      '"priorAmendments":[{"label":"First Amendment","date":"<date>"}],' +
      '"suggestedNextNumber":<integer — 1 if never amended>}' +
      "\nIf a fact is absent, use an empty string. NEVER invent dates or names.\n\nAGREEMENT TEXT (may be truncated):\n\"\"\"\n" +
      String(text || "").slice(0, 90000) + "\n\"\"\"";
    return Promise.resolve(eli.ai.complete(prompt, { sanitize: false })).then(function (raw) {
      var s2 = String(raw || "").trim().replace(/^```(?:json)?\s*/i, "").replace(/```\s*$/, "");
      var f = s2.indexOf("{"), l = s2.lastIndexOf("}");
      return JSON.parse(f !== -1 && l > f ? s2.slice(f, l + 1) : s2);
    });
  }

  // ── Section detection (deterministic) ─────────────────────────────
  function _detectSections(text) {
    var lines = String(text || "").split(/\r\n?|\n/);
    var heads = [];
    var offset = 0;
    lines.forEach(function (line) {
      var mm = line.match(/^\s*(\d+(?:\.\d+)*)[.)\s]+([A-Z][A-Za-z0-9 ,'&\/\-()]{2,70})\.?\s*$/);
      if (!mm) {
        var caps = line.match(/^\s*(\d+(?:\.\d+)*)?[.)\s]*([A-Z][A-Z0-9 ,'&\/\-()]{4,70})\s*$/);
        if (caps && caps[2] && caps[2] === caps[2].toUpperCase() && /[A-Z]{3}/.test(caps[2])) {
          mm = [caps[0], caps[1] || "", caps[2]];
        }
      }
      if (mm) heads.push({ number: mm[1] || "", label: (mm[2] || "").trim(), at: offset });
      offset += line.length + 1;
    });
    var sections = heads.map(function (h, i) {
      var end = i + 1 < heads.length ? heads[i + 1].at : text.length;
      return {
        id: "s" + i,
        number: h.number,
        label: h.label,
        text: text.slice(h.at, Math.min(end, h.at + 6000)).trim(),
      };
    });
    return sections.filter(function (sec) { return sec.text.length > 30; });
  }

  // ── Wizard chrome ─────────────────────────────────────────────────
  var STEPS = ["Intent", "Document", "Deal details", "Clauses", "Generate"];
  function _stepper() {
    return '<div class="_ab_stepper">' + STEPS.map(function (label, i) {
      var n = i + 1;
      var cls = n < S.step ? "_ab_step_done" : (n === S.step ? "_ab_step_now" : "");
      return '<div class="_ab_step ' + cls + '">' +
        '<span class="_ab_step_dot">' + (n < S.step ? "✓" : n) + '</span>' +
        '<span class="_ab_step_label">' + label + '</span>' +
      '</div>' + (n < STEPS.length ? '<div class="_ab_step_line"></div>' : '');
    }).join("") + '</div>';
  }
  function _shell(inner, opts) {
    opts = opts || {};
    return '<div class="_ab_root">' +
      '<div class="_ab_header">' +
        '<div>' +
          '<div class="_ab_title">📜 Amendment Builder</div>' +
          '<div class="_ab_subtitle">Renewals & amendments — AI reads the deal, you approve every word</div>' +
        '</div>' +
        (opts.headerRight || "") +
      '</div>' +
      _stepper() +
      '<div class="_ab_body">' + inner + '</div>' +
      '<div class="_ab_footer">' +
        (S.step > 1 ? '<button type="button" class="_ab_btn" id="_ab_back">← Back</button>' : '<span></span>') +
        (opts.footerRight || "") +
      '</div>' +
    '</div>';
  }
  function _mount(html, wire) {
    var out = window.eli.ui && typeof window.eli.ui.claimOutput === "function"
      ? window.eli.ui.claimOutput()
      : document.getElementById("output");
    if (!out) return;
    out.innerHTML = html;
    var back = document.getElementById("_ab_back");
    if (back) back.onclick = function () {
      // Pure renewal skips the clause picker (step 4) in both directions.
      S.step = (S.step === 5 && S.mode === "renew") ? 3 : Math.max(1, S.step - 1);
      _render();
    };
    if (wire) wire(out);
  }

  // ── Step 1: Intent ────────────────────────────────────────────────
  function _renderIntent() {
    var cards = [
      { mode: "renew", icon: "🔄", title: "Renew", desc: "Extend the term. Nothing else changes." },
      { mode: "renew_amend", icon: "🔄✏️", title: "Renew & amend", desc: "Extend the term AND change specific clauses." },
      { mode: "amend", icon: "✏️", title: "Amend only", desc: "Change specific clauses. Term stays as-is." },
    ];
    var noCostBlock = (S.mode === "renew" || S.mode === "renew_amend")
      ? '<div class="_ab_question">' +
          '<div class="_ab_q_label">Is this a no-cost extension?</div>' +
          '<div class="_ab_choice_row">' +
            '<button type="button" class="_ab_choice' + (S.noCost === true ? ' _ab_choice_on' : '') + '" data-nocost="1">✓ Yes — no additional fees</button>' +
            '<button type="button" class="_ab_choice' + (S.noCost === false ? ' _ab_choice_on' : '') + '" data-nocost="0">Pricing changes with this renewal</button>' +
          '</div>' +
          (S.noCost === false ? '<div class="_ab_hint">You\'ll be able to pull the pricing clause into the editor in step 4.</div>' : '') +
        '</div>'
      : "";
    var canNext = S.mode && (S.mode === "amend" || S.noCost !== null);
    _mount(_shell(
      '<div class="_ab_q_label">What do you want to do?</div>' +
      '<div class="_ab_cards">' + cards.map(function (c) {
        return '<button type="button" class="_ab_card' + (S.mode === c.mode ? ' _ab_card_on' : '') + '" data-mode="' + c.mode + '">' +
          '<span class="_ab_card_icon">' + c.icon + '</span>' +
          '<span class="_ab_card_title">' + c.title + '</span>' +
          '<span class="_ab_card_desc">' + c.desc + '</span>' +
        '</button>';
      }).join("") + '</div>' + noCostBlock,
      { footerRight: '<button type="button" class="_ab_btn _ab_btn_primary" id="_ab_next"' + (canNext ? '' : ' disabled') + '>Continue →</button>' }
    ), function (out) {
      Array.prototype.forEach.call(out.querySelectorAll("[data-mode]"), function (b) {
        b.onclick = function () {
          S.mode = b.getAttribute("data-mode");
          if (S.mode === "amend") S.noCost = null;
          _render();
        };
      });
      Array.prototype.forEach.call(out.querySelectorAll("[data-nocost]"), function (b) {
        b.onclick = function () { S.noCost = b.getAttribute("data-nocost") === "1"; _render(); };
      });
      var next = document.getElementById("_ab_next");
      if (next) next.onclick = function () { S.step = 2; _render(); };
    });
  }

  // ── Step 2: Document source ───────────────────────────────────────
  function _ingest(kind, name, textPromise, statusEl) {
    statusEl.textContent = "Reading " + name + "…";
    textPromise.then(function (text) {
      text = String(text || "");
      if (text.replace(/\s/g, "").length < 200) throw new Error("Couldn't extract meaningful text from " + name);
      S.source = { kind: kind, name: name, text: text };
      S.sections = _detectSections(text);
      statusEl.textContent = "Reading deal details with AI…";
      return _aiParseDeal(text);
    }).then(function (deal) {
      S.deal.title = deal.title || "";
      S.deal.partyA = deal.partyA || "";
      S.deal.partyB = deal.partyB || "";
      S.deal.effectiveDate = deal.effectiveDate || "";
      S.deal.termSummary = deal.termSummary || "";
      S.deal.priorAmendments = Array.isArray(deal.priorAmendments) ? deal.priorAmendments : [];
      var n = parseInt(deal.suggestedNextNumber, 10);
      S.deal.nextNumber = (!isNaN(n) && n > 0) ? n : (S.deal.priorAmendments.length + 1);
      if (deal.currentEndDate && !S.renewal.newEndDate) S.renewal.currentEndDate = deal.currentEndDate;
      S.step = 3;
      _render();
    }).catch(function (err) {
      statusEl.textContent = "";
      _toast(err && err.message || "Read failed", "err");
    });
  }
  function _renderSource() {
    _mount(_shell(
      '<div class="_ab_q_label">Where is the executed agreement?</div>' +
      '<div class="_ab_cards">' +
        '<button type="button" class="_ab_card" id="_ab_src_open">' +
          '<span class="_ab_card_icon">📄</span>' +
          '<span class="_ab_card_title">The open document</span>' +
          '<span class="_ab_card_desc">Use the document currently open in Word.</span>' +
        '</button>' +
        '<button type="button" class="_ab_card" id="_ab_src_upload">' +
          '<span class="_ab_card_icon">📁</span>' +
          '<span class="_ab_card_title">Upload a file</span>' +
          '<span class="_ab_card_desc">Word (.docx) or PDF of the signed agreement.</span>' +
        '</button>' +
      '</div>' +
      '<input type="file" id="_ab_file" accept=".docx,.pdf" style="display:none;">' +
      '<div class="_ab_status" id="_ab_src_status"></div>'
    ), function (out) {
      var statusEl = document.getElementById("_ab_src_status");
      document.getElementById("_ab_src_open").onclick = function () {
        _ingest("open", "the open document", _readOpenDoc(), statusEl);
      };
      var fileInput = document.getElementById("_ab_file");
      document.getElementById("_ab_src_upload").onclick = function () { fileInput.click(); };
      fileInput.onchange = function () {
        var f = fileInput.files && fileInput.files[0];
        if (!f) return;
        var isPdf = /\.pdf$/i.test(f.name);
        _ingest(isPdf ? "pdf" : "docx", f.name, isPdf ? _readPdfFile(f) : _readDocxFile(f), statusEl);
      };
    });
  }

  // ── Step 3: Deal details (AI-prefilled, all editable) ────────────
  function _renderDetails() {
    function fld(id, label, value, hint) {
      return '<label class="_ab_fld"><span class="_ab_fld_label">' + label + '</span>' +
        '<input type="text" class="_ab_inp" id="' + id + '" value="' + _esc(value) + '">' +
        (hint ? '<span class="_ab_hint">' + hint + '</span>' : '') + '</label>';
    }
    var isRenew = S.mode === "renew" || S.mode === "renew_amend";
    var priorTxt = (S.deal.priorAmendments || []).map(function (p) {
      return (p.label || "?") + (p.date ? " (" + p.date + ")" : "");
    }).join("; ") || "None found";
    _mount(_shell(
      '<div class="_ab_q_label">Deal details <span class="_ab_q_sub">— AI-read from the document; correct anything that\'s wrong</span></div>' +
      (S.deal.termSummary ? '<div class="_ab_termcard">📋 ' + _esc(S.deal.termSummary) + '</div>' : '') +
      '<div class="_ab_grid">' +
        fld("_ab_d_title", "Agreement title", S.deal.title) +
        fld("_ab_d_pa", "Party A", S.deal.partyA) +
        fld("_ab_d_pb", "Party B", S.deal.partyB) +
        fld("_ab_d_eff", "Original effective date", S.deal.effectiveDate) +
        fld("_ab_d_num", "This amendment is No.", String(S.deal.nextNumber), "Prior: " + _esc(priorTxt)) +
        fld("_ab_d_date", "Amendment date", S.amendmentDate) +
        (isRenew
          ? fld("_ab_d_end", "New expiration date", S.renewal.newEndDate,
              S.renewal.currentEndDate ? "Current expiration: " + _esc(S.renewal.currentEndDate) : "") +
            fld("_ab_d_ext", "Extension length (optional)", S.renewal.extendText, "e.g. “an additional two (2) year term”")
          : '') +
      '</div>',
      { footerRight: '<button type="button" class="_ab_btn _ab_btn_primary" id="_ab_next">Continue →</button>' }
    ), function () {
      document.getElementById("_ab_next").onclick = function () {
        S.deal.title = document.getElementById("_ab_d_title").value;
        S.deal.partyA = document.getElementById("_ab_d_pa").value;
        S.deal.partyB = document.getElementById("_ab_d_pb").value;
        S.deal.effectiveDate = document.getElementById("_ab_d_eff").value;
        S.deal.nextNumber = document.getElementById("_ab_d_num").value;
        S.amendmentDate = document.getElementById("_ab_d_date").value;
        var isRenew2 = S.mode === "renew" || S.mode === "renew_amend";
        if (isRenew2) {
          S.renewal.newEndDate = document.getElementById("_ab_d_end").value;
          S.renewal.extendText = document.getElementById("_ab_d_ext").value;
          if (!S.renewal.newEndDate.trim()) { _toast("Enter the new expiration date", "err"); return; }
        }
        S.step = (S.mode === "renew") ? 5 : 4;   // pure renewal skips clause picking
        _render();
      };
    });
  }

  // ── Step 4: Clause selection + editing ────────────────────────────
  function _renderClauses() {
    var listHtml = S.sections.length
      ? S.sections.map(function (sec) {
          var on = !!S.selected[sec.id];
          return '<div class="_ab_sec' + (on ? ' _ab_sec_on' : '') + '">' +
            '<label class="_ab_sec_head">' +
              '<input type="checkbox" data-sec="' + sec.id + '"' + (on ? ' checked' : '') + '>' +
              '<span class="_ab_sec_label">' + (sec.number ? '§' + _esc(sec.number) + ' · ' : '') + _esc(sec.label) + '</span>' +
            '</label>' +
            (on
              ? '<div class="_ab_sec_edit">' +
                  '<details class="_ab_sec_orig"><summary>Original text</summary><div>' + _esc(sec.text) + '</div></details>' +
                  '<div class="_ab_fld_label">Replacement text</div>' +
                  '<textarea class="_ab_ta" data-edit="' + sec.id + '" rows="7">' + _esc(S.edits[sec.id] != null ? S.edits[sec.id] : sec.text) + '</textarea>' +
                '</div>'
              : '') +
          '</div>';
        }).join("")
      : '<div class="_ab_hint">No section headings detected in the source text. You can still add a freeform amendment in the next step\'s preview, or go back and try the Word version of the document.</div>';
    var pickedCount = Object.keys(S.selected).filter(function (k) { return S.selected[k]; }).length;
    _mount(_shell(
      '<div class="_ab_q_label">Which clauses are you amending? <span class="_ab_q_sub">— tick a clause to pull its text into the editor</span></div>' +
      '<input type="text" class="_ab_inp _ab_filter" id="_ab_filter" placeholder="Filter clauses…">' +
      '<div class="_ab_sections" id="_ab_sections">' + listHtml + '</div>',
      { footerRight: '<button type="button" class="_ab_btn _ab_btn_primary" id="_ab_next">' +
          (pickedCount ? 'Continue with ' + pickedCount + ' clause' + (pickedCount === 1 ? '' : 's') + ' →' : 'Continue →') + '</button>' }
    ), function (out) {
      Array.prototype.forEach.call(out.querySelectorAll("[data-sec]"), function (cb) {
        cb.onchange = function () {
          _saveEdits(out);
          S.selected[cb.getAttribute("data-sec")] = cb.checked;
          _render();
        };
      });
      var filter = document.getElementById("_ab_filter");
      if (filter) filter.oninput = function () {
        var q = filter.value.toLowerCase();
        Array.prototype.forEach.call(out.querySelectorAll("._ab_sec"), function (el, i) {
          var sec = S.sections[i];
          var hay = ((sec.number || "") + " " + (sec.label || "") + " " + sec.text.slice(0, 400)).toLowerCase();
          el.style.display = !q || hay.indexOf(q) !== -1 ? "" : "none";
        });
      };
      document.getElementById("_ab_next").onclick = function () {
        _saveEdits(out);
        S.step = 5;
        _render();
      };
    });
  }
  function _saveEdits(out) {
    Array.prototype.forEach.call(out.querySelectorAll("[data-edit]"), function (ta) {
      S.edits[ta.getAttribute("data-edit")] = ta.value;
    });
  }

  // ── Step 5: Generate + deliver ────────────────────────────────────
  function _renderGenerate() {
    if (typeof buildAmendment !== "function") {
      _mount(_shell('<div class="_ab_hint">Engine missing — reinstall the tool bundle.</div>'));
      return;
    }
    var clauseEdits = S.sections.filter(function (sec) { return S.selected[sec.id]; })
      .map(function (sec) {
        return { number: sec.number, label: sec.label, originalText: sec.text, newText: S.edits[sec.id] != null ? S.edits[sec.id] : sec.text };
      });
    var result = buildAmendment({
      mode: S.mode, noCost: !!S.noCost,
      deal: S.deal, renewal: S.renewal,
      clauseEdits: clauseEdits, amendmentDate: S.amendmentDate,
    });
    S.generated = result;
    _mount(_shell(
      '<div class="_ab_q_label">Your amendment <span class="_ab_q_sub">— assembled from templates + your inputs; nothing here was AI-written</span></div>' +
      '<div class="_ab_deliver_row">' +
        '<button type="button" class="_ab_btn _ab_btn_primary" id="_ab_insert">⬇️ Insert at cursor</button>' +
        '<button type="button" class="_ab_btn" id="_ab_copytext">📋 Copy as text</button>' +
      '</div>' +
      '<div class="_ab_hint">Insert into a blank document (File → New in Word, place your cursor, then click Insert).</div>' +
      '<div class="_ab_preview">' + result.bodyHtml + '</div>'
    ), function () {
      document.getElementById("_ab_insert").onclick = function () {
        eli.host.runRaw("amend:insert", function (context) {
          var sel = context.document.getSelection();
          sel.insertHtml(result.bodyHtml, "Replace");
          return context.sync();
        }).then(function () { _toast("✓ Inserted", "ok"); })
          .catch(function (err) { _toast("Insert failed: " + (err && err.message || "unknown"), "err"); });
      };
      document.getElementById("_ab_copytext").onclick = function () {
        var ta = document.createElement("textarea");
        ta.value = result.bodyText;
        ta.style.cssText = "position:fixed;left:-9999px;opacity:0;";
        document.body.appendChild(ta);
        ta.select();
        var ok = false;
        try { ok = document.execCommand("copy"); } catch (_e) {}
        document.body.removeChild(ta);
        _toast(ok ? "Copied" : "Copy failed", ok ? "ok" : "err");
      };
      try { eli.log.event("tool", "amendment_generated", { mode: S.mode, clauses: clauseEdits.length, noCost: !!S.noCost }); } catch (_e) {}
    });
  }

  function _render() {
    if (S.step === 1) return _renderIntent();
    if (S.step === 2) return _renderSource();
    if (S.step === 3) return _renderDetails();
    if (S.step === 4) return _renderClauses();
    return _renderGenerate();
  }

  function _launch() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedAmendment"); } catch (_e) {}
    S = _freshState();
    _render();
  }

  if (eli.register) {
    eli.register({
      tile: {
        app_amendment_builder: eli.events && eli.events.guard
          ? eli.events.guard(function () { _launch(); }, "amendment_builder.tile")
          : function () { _launch(); },
      },
    });
  }
  if (eli.log && eli.log.event) eli.log.event("tool", "amendment_builder_initialized", {});
}

jsonTools.css:
/* Amendment Builder — premium wizard. Light root over dark dashboard,
   navy/gold header, squared corners, platinum grays. */

#output:has(._ab_root) { background: #f8fafc; }

._ab_root {
  flex: 1 0 auto;
  background: #f8fafc;
  font-family: Inter, "Segoe UI", system-ui, -apple-system, sans-serif;
  color: #0f172a;
  min-height: 100%;
  display: flex;
  flex-direction: column;
}

._ab_header {
  background: linear-gradient(120deg, #12346f, #1d4a94 44%, #3b82f6);
  border-bottom: 2px solid #d4a237;
  color: #fff;
  padding: 14px 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
._ab_title { font-size: 17px; font-weight: 800; letter-spacing: 0.02em; }
._ab_subtitle { font-size: 11px; font-weight: 500; color: #dbeafe; margin-top: 3px; }

._ab_stepper {
  display: flex;
  align-items: center;
  padding: 12px 18px;
  background: #fff;
  border-bottom: 1px solid #e2e8f0;
  overflow-x: auto;
}
._ab_step { display: flex; align-items: center; gap: 6px; flex-shrink: 0; }
._ab_step_dot {
  width: 22px; height: 22px;
  display: inline-flex; align-items: center; justify-content: center;
  font: 800 11px/1 Inter, sans-serif;
  border: 1px solid #cbd5e1;
  background: #f8fafc;
  color: #94a3b8;
}
._ab_step_label {
  font: 700 10px/1.2 Inter, sans-serif;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #94a3b8;
  white-space: nowrap;
}
._ab_step_now ._ab_step_dot { background: #12346f; border-color: #12346f; color: #fff; }
._ab_step_now ._ab_step_label { color: #12346f; }
._ab_step_done ._ab_step_dot { background: #dcfce7; border-color: #86efac; color: #166534; }
._ab_step_done ._ab_step_label { color: #166534; }
._ab_step_line { flex: 0 0 18px; height: 1px; background: #e2e8f0; margin: 0 8px; }

._ab_body { flex: 1; padding: 16px 18px; }
._ab_footer {
  padding: 12px 18px;
  background: #fff;
  border-top: 1px solid #e2e8f0;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

._ab_q_label { font: 800 14px/1.4 Inter, sans-serif; color: #0f172a; margin-bottom: 12px; }
._ab_q_sub { font: 500 11px/1.4 Inter, sans-serif; color: #64748b; }
._ab_hint { font: 500 11px/1.5 Inter, sans-serif; color: #64748b; margin-top: 8px; }
._ab_status { font: 600 12px/1.5 Inter, sans-serif; color: #1e40af; margin-top: 12px; min-height: 18px; }

._ab_cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 10px; }
._ab_card {
  display: flex; flex-direction: column; align-items: flex-start; gap: 6px;
  padding: 16px 14px;
  background: linear-gradient(180deg, #ffffff 0%, #f6f8fb 100%);
  border: 1px solid #cbd5e1;
  border-radius: 0;
  cursor: pointer;
  text-align: left;
  transition: border-color 0.12s, box-shadow 0.12s, transform 0.08s;
}
._ab_card:hover {
  border-color: #1d4a94;
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(15, 23, 42, 0.08);
}
._ab_card_on {
  border: 2px solid #12346f;
  background: linear-gradient(180deg, #eff6ff 0%, #dbeafe 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.8);
}
._ab_card_icon { font-size: 22px; }
._ab_card_title { font: 800 13px/1.2 Inter, sans-serif; color: #0f172a; }
._ab_card_desc { font: 500 11px/1.5 Inter, sans-serif; color: #64748b; }

._ab_question { margin-top: 16px; }
._ab_choice_row { display: flex; gap: 8px; flex-wrap: wrap; }
._ab_choice {
  font: 700 12px/1.2 Inter, sans-serif;
  padding: 9px 14px;
  background: linear-gradient(180deg, #ffffff 0%, #f1f5f9 100%);
  border: 1px solid #cbd5e1;
  border-radius: 0;
  color: #334155;
  cursor: pointer;
}
._ab_choice:hover { border-color: #1d4a94; }
._ab_choice_on {
  background: linear-gradient(180deg, #eff6ff 0%, #dbeafe 100%);
  border: 2px solid #12346f;
  color: #12346f;
}

._ab_btn {
  font: 700 12px/1.2 Inter, sans-serif;
  letter-spacing: 0.03em;
  padding: 9px 16px;
  border-radius: 0;
  cursor: pointer;
  border: 1px solid #cbd5e1;
  background: linear-gradient(180deg, #ffffff 0%, #f1f5f9 100%);
  color: #0f172a;
}
._ab_btn:hover:not(:disabled) { border-color: #94a3b8; }
._ab_btn:disabled { opacity: 0.5; cursor: default; }
._ab_btn_primary {
  background: linear-gradient(135deg, #1d4a94, #12346f);
  border-color: #12346f;
  color: #fff;
}
._ab_btn_primary:hover:not(:disabled) { background: linear-gradient(135deg, #12346f, #0b264f); }

._ab_termcard {
  font: 600 12px/1.6 Inter, sans-serif;
  color: #5b3a05;
  background: linear-gradient(180deg, #fffdf4, #fff6d9);
  border: 1px solid #f2d084;
  border-left: 3px solid #d4a237;
  padding: 9px 12px;
  margin-bottom: 12px;
}

._ab_grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; }
._ab_fld { display: flex; flex-direction: column; gap: 4px; }
._ab_fld_label {
  font: 700 10px/1.2 Inter, sans-serif;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #475569;
}
._ab_inp {
  padding: 8px 10px;
  font: 500 13px/1.3 Inter, sans-serif;
  border: 1px solid #cbd5e1;
  border-radius: 0;
  background: #fff;
  color: #0f172a;
}
._ab_inp:focus { outline: 2px solid #1d4a94; outline-offset: -1px; }
._ab_filter { width: 100%; box-sizing: border-box; margin-bottom: 10px; }

._ab_sections { display: flex; flex-direction: column; gap: 8px; }
._ab_sec { background: #fff; border: 1px solid #e2e8f0; border-radius: 0; }
._ab_sec_on { border-color: #12346f; border-left: 3px solid #12346f; }
._ab_sec_head {
  display: flex; align-items: center; gap: 8px;
  padding: 9px 12px;
  cursor: pointer;
  user-select: none;
}
._ab_sec_head input { accent-color: #12346f; width: 15px; height: 15px; flex-shrink: 0; }
._ab_sec_label { font: 700 12px/1.4 Inter, sans-serif; color: #0f172a; }
._ab_sec_edit { padding: 0 12px 12px; }
._ab_sec_orig { margin-bottom: 8px; }
._ab_sec_orig summary {
  font: 700 10px/1.4 Inter, sans-serif;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #64748b;
  cursor: pointer;
}
._ab_sec_orig div {
  font: 400 12px/1.6 Georgia, "Times New Roman", serif;
  color: #475569;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  padding: 8px 10px;
  margin-top: 4px;
  max-height: 180px;
  overflow: auto;
  white-space: pre-wrap;
}
._ab_ta {
  width: 100%;
  box-sizing: border-box;
  padding: 9px 10px;
  font: 400 13px/1.6 Georgia, "Times New Roman", serif;
  border: 1px solid #cbd5e1;
  border-radius: 0;
  background: #fffef8;
  color: #0f172a;
  resize: vertical;
}
._ab_ta:focus { outline: 2px solid #1d4a94; outline-offset: -1px; }

._ab_deliver_row { display: flex; gap: 8px; margin-bottom: 4px; }
._ab_preview {
  margin-top: 12px;
  background: #fff;
  border: 1px solid #cbd5e1;
  padding: 26px 32px;
  font: 400 13px/1.75 Georgia, "Times New Roman", serif;
  color: #0f172a;
  box-shadow: 0 2px 10px rgba(15, 23, 42, 0.06);
  max-height: 60vh;
  overflow: auto;
}
._ab_preview p { margin: 0 0 12px; }
